mapper.select:
SELECT co.*, c.name as courseName, c.course_no as courseNo, t.name as teacherName, s.name as semesterName, c.credits as credits, c.category as category FROM course_offer co LEFT JOIN course c ON co.course_id = c.id AND c.deleted = 0 LEFT JOIN teacher t ON co.teacher_id = t.id AND t.deleted = 0 LEFT JOIN semester s ON co.semester_id = s.id AND s.deleted = 0
co.deleted = 0 AND co.course_id = #{params.courseId} AND co.teacher_id = #{params.teacherId} AND co.semester_id = #{params.semesterId}
ORDER BY co.create_time DESC

SELECT co.*, c.name as courseName, c.course_no as courseNo, t.name as teacherName, s.name as semesterName, c.credits as credits, c.category as category FROM course_offer co LEFT JOIN course c ON co.course_id = c.id AND c.deleted = 0 LEFT JOIN teacher t ON co.teacher_id = t.id AND t.deleted = 0 LEFT JOIN semester s ON co.semester_id = s.id
co.deleted = 0 AND co.course_id = #{courseId} AND co.teacher_id = #{teacherId} AND co.semester_id = #{semesterId}
ORDER BY co.create_time DESC

mapper.update:
UPDATE course_offer
SET enrolled = enrolled + 1, version = version + 1
WHERE id = #{id} AND deleted = 0 AND enrolled < max_students AND version = #{version}

UPDATE course_offer
SET enrolled = enrolled - 1, version = version + 1
WHERE id = #{id} AND deleted = 0 AND enrolled > 0 AND version = #{version}
